function payMultIdx(s){const cur=s.payMult||1;let bi=0,bd=1e18;PAYMULTS.forEach((v,i)=>{const d=Math.abs(v-cur);if(d<bd){bd=d;bi=i}});return bi}
function applyPayMult(sid,idx){const s=S.scenarios.find(x=>x.id===sid);if(!s)return;const nv=PAYMULTS[Math.max(0,Math.min(PAYMULTS.length-1,Math.round(idx)))];const ov=s.payMult||1;if(nv!==ov){const f=nv/ov;(s.objectives||[]).forEach(o=>{o.payout=Math.max(0,Math.round((+o.payout||0)*f))});s.payMult=nv;clog(s,'Payout multiplier x'+ov+' -> x'+nv+' — all objective payouts rescaled')}if(OD&&OD.scenarioId===s.id&&OD.brigadeId){const keep={};(OD.pay||[]).forEach(w=>keep[w.oid]=w.awarded);OD.pay=scopedPay(s,OD.brigadeId).map(w=>{const aw=keep[w.oid];return aw===undefined?w:{oid:w.oid,text:w.text,amount:w.amount,awarded:aw}});OD.payScen=s.id+':'+OD.brigadeId}save();renderAll();toast('Payout multiplier x'+nv)}
