function syncDlg(b){return new Promise(res=>{
const ov=document.getElementById('dlgOverlay');if(!ov)return res(null);
const cands=S.series.filter(s=>s.id!==S.activeSeriesId&&((s.snap.brigades||[]).some(o=>o.name===b.name)));
if(!cands.length){toast(`No brigade named '${b.name}' in any other series`);return res(null)}
const T=document.getElementById('dlgTitle'),M=document.getElementById('dlgMsg'),ok=document.getElementById('dlgOk'),cx=document.getElementById('dlgCancel');
T.textContent=`Sync '${b.name}'`;
M.innerHTML=`<p class="hint">Copy roster, mechs, ledger and memorial from the same-named brigade in:</p><label>Series <select id="syncSeries" style="width:100%">${cands.map(s=>{const o=(s.snap.brigades||[]).find(x=>x.name===b.name);return `<option value="${s.id}">${s.name} (${(o.inventory||[]).length} mechs, ${(o.roster||[]).length} pilots)</option>`}).join('')}</select></label><p class="hint">This overwrites '${b.name}' here (its name and id stay).</p>`;
ok.textContent='Sync';
ov.hidden=false;ok.focus();
const done=v=>{ov.hidden=true;ok.onclick=null;cx.onclick=null;ov.onclick=null;document.removeEventListener('keydown',esc);ok.textContent='Confirm';T.textContent='Confirm';M.textContent='';res(v)};
const esc=e=>{if(e.key==='Escape')done(null)};
ok.onclick=()=>done(document.getElementById('syncSeries').value||null);
cx.onclick=()=>done(null);
ov.onclick=e=>{if(e.target===ov)done(null)};
document.addEventListener('keydown',esc)})}
el.querySelectorAll('[data-share]').forEach(x=>x.onclick=async()=>{const b=S.brigades.find(v=>v.id===x.dataset.share);if(!b)return;try{
const blob=brigadeODS(b),fname=((b.name||'brigade').replace(/[\\/:*?"<>|]/g,'').trim().slice(0,60)||'brigade')+'.ods';
const file=new File([blob],fname,{type:'application/vnd.oasis.opendocument.spreadsheet'});
const dlFallback=why=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fname;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000);blog(b,'Brigade exported (ODS download — '+why+')');save();renderBrigs();toast(why+' — ODS downloaded instead')};
if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:`Brigade: ${b.name}`,text:`${b.name} — ${(b.inventory||[]).length} mechs, ${(b.roster||[]).length} pilots`});blog(b,'Brigade shared via Web Share (ODS)');save();renderBrigs();toast('Brigade shared')}
catch(serr){if(serr&&serr.name==='AbortError'){toast('Share cancelled');return}const smsg=String((serr&&(serr.message||serr.name))||'share failed');if(serr&&(serr.name==='NotAllowedError'||serr.name==='SecurityError'||/permission denied/i.test(smsg))){console.warn(serr);dlFallback('Share permission denied');return}throw serr}}
else dlFallback('Web Share unavailable');
}catch(err){if(err&&err.name==='AbortError'){toast('Share cancelled');return}const emsg=String((err&&(err.message||err.name))||'share failed');if(/permission denied/i.test(emsg)||(err&&(err.name==='NotAllowedError'||err.name==='SecurityError'))){try{const blob2=brigadeODS(b),fname2=((b.name||'brigade').replace(/[\\/:*?"<>|]/g,'').trim().slice(0,60)||'brigade')+'.ods';const a=document.createElement('a');a.href=URL.createObjectURL(blob2);a.download=fname2;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000);blog(b,'Brigade exported (ODS download — Share permission denied)');save();renderBrigs();toast('Share permission denied — ODS downloaded instead')}catch(dlerr){console.warn(dlerr);toast('Share failed: '+emsg)}return}console.warn(err);toast('Share failed: '+emsg)}});
