function commitDateDlg(cands){return new Promise(res=>{
const ov=document.getElementById('dlgOverlay');if(!ov)return res(null);
const T=document.getElementById('dlgTitle'),M=document.getElementById('dlgMsg'),ok=document.getElementById('dlgOk'),cx=document.getElementById('dlgCancel');
T.textContent='Assign to game date';
const ordered=[...cands].sort((a,b)=>a.date.localeCompare(b.date));
const upId=upcomingGameId();
const defId=ordered.some(g=>g.id===upId)?upId:(ordered[0]||{}).id;
M.innerHTML=`<p class="hint">More than one upcoming game date is open — pick the date this contract is assigned to (only dates without a committed contract are listed):</p><label>Game date <select id="commitDate" size="5" style="width:100%">${ordered.map(g=>{const nt=String(g.note||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');return `<option value="${g.id}"${g.id===defId?' selected':''}>${g.date}${nt?' — '+nt:''} [${g.mode||S.mode||'TW'}]${g.id===upId?' ★':''}</option>`}).join('')}</select></label>`;
ok.textContent='Commit';
ov.hidden=false;ok.focus();
const done=v=>{ov.hidden=true;ok.onclick=null;cx.onclick=null;ov.onclick=null;document.removeEventListener('keydown',esc);ok.textContent='Confirm';T.textContent='Confirm';M.textContent='';res(v)};
const esc=e=>{if(e.key==='Escape')done(null)};
ok.onclick=()=>done(document.getElementById('commitDate').value||null);
cx.onclick=()=>done(null);
ov.onclick=e=>{if(e.target===ov)done(null)};
document.addEventListener('keydown',esc)})}
async function commitSign(id){const t=S.scenarios.find(y=>y.id===id);if(!t)return;
const today=todayStr();
const cands=S.dates.filter(g=>g.status!=='cancelled'&&!g.locked&&g.date>=today&&!S.scenarios.some(x=>x.id!==t.id&&x.gameDateId===g.id&&x.status==='active'));
let gid=t.gameDateId;
if(cands.length===1)gid=cands[0].id;
else if(cands.length>1){const pick=await commitDateDlg(cands);if(!pick)return;gid=pick}
t.gameDateId=gid;
S.scenarios.forEach(x=>{if(x.id!==t.id&&x.gameDateId===gid&&x.status==='active')x.status='available'});
t.status='active';S.activePredrop=t.id;S.predropDateId=t.gameDateId;clog(t,`Committed and signed${(S.dates.find(g=>g.id===gid)||{}).date?` for ${(S.dates.find(g=>g.id===gid)||{}).date}`:''}`);
const _gd0=S.dates.find(g=>g.id===gid);if(_gd0&&(_gd0.mode==='TW'||_gd0.mode==='AS')&&_gd0.mode!==S.mode)setMode(_gd0.mode);
save();renderAll();const _pd=document.querySelector('.tab[data-tab="predrop"]');if(_pd)_pd.click();
const gd=S.dates.find(g=>g.id===gid);toast(`Committed and signed: '${t.title}'${gd?` for ${gd.date}`:''}`)}
function undoCommit(id){const t=S.scenarios.find(y=>y.id===id);if(!t||t.status!=='active')return;
const g=S.dates.find(x=>x.id===t.gameDateId);
if(g&&g.date<todayStr()){toast('Cannot undo — the game date is in the past');return}
t.status='available';if(S.activePredrop===t.id)S.activePredrop=null;clog(t,'Commit undone — back to available');save();renderAll();toast(`Commit undone: '${t.title}' is available again`)}
function focusPredrop(s){if(!s||s.status!=='active')return;S.activePredrop=s.id;if(s.gameDateId)S.predropDateId=s.gameDateId}
function toggleParticipation(sid,bid,on){const s=S.scenarios.find(x=>x.id===sid),b=S.brigades.find(x=>x.id===bid);if(!s||!b)return;s.sides=s.sides||[];
if(on){if(s.sides.some(x=>x.brigadeId===bid))return;clog(s,`'${b.name}' joined the contract`);const used=s.sides.map(x=>x.role);const role=!used.includes('Attacker')?'Attacker':!used.includes('Defender')?'Defender':'Raider';const sd={id:uid(),role,brigadeId:bid};const _newRole=!used.includes(role);s.sides.push(sd);const m=MISSIONS.find(x=>x.t===s.type);if(m){s.objectives.push(...genSideObjectives(m,sd,b,perSideShare(m,s.sides,sd.role,s.payMult||1)));if(_newRole)rebalanceSidePayouts(s,true);else{s.objectives.filter(o=>o.sideId===sd.id&&!isOpp(o)).forEach(o=>{o.payout=0});evenRolePreserve(s,sd.role)}}else s.objectives.push({id:uid(),text:`${b.name}: take the field`,payout:0,enabled:true,required:true,auto:false,by:bid,sideId:sd.id});focusPredrop(s);refreshBackstory(s);save();renderAll();toast(`'${b.name}' joined as ${role}`)}
else{const sd=s.sides.find(x=>x.brigadeId===bid);if(!sd)return;clog(s,`'${b.name}' left the contract`);const _role=sd.role||'Unassigned',_pot=roleKeyTotal(s,_role);s.sides=s.sides.filter(x=>x!==sd);s.objectives=(s.objectives||[]).filter(o=>o.sideId!==sd.id);if(_pot>0)evenRoleKeys(s,_role,_pot);else evenRolePreserve(s,_role);refreshBackstory(s);save();renderAll();toast(`'${b.name}' left the contract`)}}
function setSideRole(sid,bid,role){const s=S.scenarios.find(x=>x.id===sid);const sd=s&&(s.sides||[]).find(x=>x.brigadeId===bid);if(!sd||sd.role===role)return;const _old=sd.role||'Unassigned',_rb=new Set(s.sides.map(x=>x.role)),_potA=roleKeyTotal(s,_old);sd.role=role;const b=S.brigades.find(x=>x.id===bid);const m=MISSIONS.find(x=>x.t===s.type);if(m){s.objectives=(s.objectives||[]).filter(o=>o.sideId!==sd.id);s.objectives.push(...genSideObjectives(m,sd,b,perSideShare(m,s.sides,sd.role,s.payMult||1)));const _ra=new Set(s.sides.map(x=>x.role));if(_ra.size!==_rb.size)rebalanceSidePayouts(s,true);else{s.objectives.filter(o=>o.sideId===sd.id&&!isOpp(o)).forEach(o=>{o.payout=0});if(_potA>0)evenRoleKeys(s,_old,_potA);else evenRolePreserve(s,_old);evenRolePreserve(s,sd.role||'Unassigned')}clog(s,`'${(b&&b.name)||bid}' switched side to ${role} — objectives re-issued for the new side`)}else clog(s,`'${(b&&b.name)||bid}' switched side to ${role}`);focusPredrop(s);refreshBackstory(s);save();renderAll()}
function setRequired(sid,oid,val){const s=S.scenarios.find(x=>x.id===sid);const o=s&&(s.objectives||[]).find(x=>x.id===oid);if(!o)return;if(!val){const others=(s.objectives||[]).filter(x=>x.sideId===o.sideId&&x.id!==o.id&&x.required);if(!others.length){toast('Each side needs at least one required objective');save();renderScens();return}}o.required=!!val;save();renderScens()}
function salvageGroups(s){const groups=[],byRole={};(s.sides||[]).forEach(sd=>{if(!sd||!sd.brigadeId)return;const b=S.brigades.find(x=>x.id===sd.brigadeId);if(!b)return;const r=sd.role||'No side';if(!byRole[r]){byRole[r]=[];groups.push({role:r,ids:byRole[r]})}byRole[r].push(b.id)});const ord=r=>{const i=SIDE_ROLES.indexOf(r);return i<0?99:i};groups.sort((a,b)=>ord(a.role)-ord(b.role));return groups}
function normalizeSalvage(s){if(!s.salvage)s.salvage={};const before=JSON.stringify(s.salvage);salvageGroups(s).forEach(g=>{if(g.ids.length===1){s.salvage[g.ids[0]]=100;return}const vals=g.ids.map(id=>Math.max(0,Math.round(+s.salvage[id]||0)));const sum=vals.reduce((a,b)=>a+b,0);if(sum<=0||g.ids.some(id=>s.salvage[id]==null)){const base=Math.floor(100/g.ids.length),rem=100-base*g.ids.length;g.ids.forEach((id,i)=>s.salvage[id]=base+(i<rem?1:0));return}if(sum!==100){let acc=0;g.ids.forEach((id,i)=>{if(i<g.ids.length-1){const v=Math.round(vals[i]*100/sum);s.salvage[id]=v;acc+=v}else s.salvage[id]=100-acc})}});if(JSON.stringify(s.salvage)!==before)save()}
function balanceSalvageSide(sc,ids,keepId){if(!ids.length)return;const keep=Math.max(0,Math.min(100,Math.round(+sc.salvage[keepId]||0)));sc.salvage[keepId]=keep;const others=ids.filter(id=>id!==keepId);if(!others.length){sc.salvage[keepId]=100;return}const base=Math.floor((100-keep)/others.length),rem=(100-keep)-base*others.length;others.forEach((id,i)=>sc.salvage[id]=base+(i<rem?1:0))}
function salvageRightsH(s){const groups=salvageGroups(s);let h='<h4>Salvage Rights % <span class="hint">(split per side)</span></h4>';if(!groups.length)return h+'<p class="hint">No brigades on this contract yet \u2014 tick a brigade above to take part.</p>';groups.forEach(g=>{h+='<div class="catbox"><h5>'+g.role+' side</h5>';if(g.role==='Raider'){h+='<div class="row"><label class="check"><input type="checkbox" data-spoils="'+s.id+'"'+(s.spoils?' checked':'')+'> To the Victor Goes the Spoils</label></div><p class="hint">Raiders go last-man-standing: no fixed split \u2014 the standing side takes all (unless they flee).</p>'};if(g.ids.length===1){const b0=S.brigades.find(x=>x.id===g.ids[0]);h+='<p>'+(b0?b0.name:'?')+' \u2014 <b>100% rights if victorious</b></p>'}else{const dis=(g.role==='Raider'&&s.spoils)?' disabled':'';g.ids.forEach(id=>{const b=S.brigades.find(x=>x.id===id);const v=s.salvage[id]||0;h+='<div class="row"><span>'+(b?b.name:'?')+'</span><input type="range" min="0" max="100" value="'+v+'" data-sal="'+s.id+':'+id+'"'+dis+'><span data-salv="'+s.id+':'+id+'">'+v+'%</span></div>'})}h+='</div>'});const bench=S.brigades.filter(b=>!(s.sides||[]).some(sd=>sd&&sd.brigadeId===b.id));if(bench.length)h+='<p class="hint">Not on this contract (no rights): '+bench.map(b=>b.name).join(', ')+'</p>';return h}
